import { isGlobalId } from '../../';

describe('isGlobalId', () => {
  it('should be global id', () => {
    expect(isGlobalId('000001882582a2cc4e548a4c337b4d87')).toEqual(true);
  });

  it('should not be global id', () => {
    expect(isGlobalId('1882582a2cc4e548a4c337b4d87')).toEqual(false);
  });
});
